RULE_NOTE = ("The rules on this site read structured figures; most cases here turned on information that was not public at the time (internal emails, "
             "side agreements, bank records). The library teaches the mechanism and what public evidence would have raised the question; it does not claim the rules would have caught the case.")


def by_rule():
    out = {}
    for c in CASES:
        for r in c[8]:
            out.setdefault(r, {"cases": [], "papers": []})["cases"].append(c[0])
    for p in PAPERS:
        for r in p[6]:
            out.setdefault(r, {"cases": [], "papers": []})["papers"].append(p[0])
    return out
